#[test]
fn test_process_block_matches_process() {
    let lambda = bark_lambda(48000.0_f64);
    let mut sample_by_sample =
        WarpedBiquad::new(BiquadFilterType::Peak, 400.0, 48000.0, 2.0, -3.0, lambda);
    let mut block = WarpedBiquad::new(BiquadFilterType::Peak, 400.0, 48000.0, 2.0, -3.0, lambda);

    let signal: Vec<f64> = (0..256).map(|i| ((i as f64) * 0.05).sin()).collect();
    let mut block_signal = signal.clone();

    let mut expected: Vec<f64> = Vec::with_capacity(256);
    for &x in &signal {
        expected.push(sample_by_sample.process(x));
    }

    block.process_block(&mut block_signal);

    for (i, (&e, &g)) in expected.iter().zip(block_signal.iter()).enumerate() {
        assert!(
            (e - g).abs() < 1e-14,
            "process vs process_block mismatch at sample {}: {} vs {}",
            i,
            e,
            g
        );
    }
}

#[test]
fn test_small_denom_clamped_f32() {
    // Issue #3: compute_implicit_consts uses an absolute 1e-15 threshold
    // that is smaller than f32::EPSILON.  For a raw denominator of ~1e-6
    // the old code returns inv_denom ≈ 1e6, which is numerically unstable.
    let lambda = 0.876f32;
    // Coefficients chosen so that raw_denom ≈ 1e-6 in f32 arithmetic.
    let a1 = (1e-6f32 - 1.0f32) / lambda;
    let (inv_denom, _) = compute_implicit_consts::<f32>(a1, 0.0f32, lambda);
    // After the fix inv_denom should be clamped to a reasonable magnitude.
    assert!(
        inv_denom.abs() < 1e4,
        "inv_denom should be clamped for small denominators in f32, got {}",
        inv_denom
    );
}

#[test]
fn test_small_denom_preserves_sign_f32() {
    // When the denominator is clamped the sign must be preserved so that
    // the filter phase is not silently flipped.
    let lambda = 0.876f32;
    // Negative raw_denom ≈ -1e-6
    let a1 = (-1e-6f32 - 1.0f32) / lambda;
    let (inv_denom, _) = compute_implicit_consts::<f32>(a1, 0.0f32, lambda);
    assert!(
        inv_denom < 0.0,
        "clamped inv_denom should preserve negative sign, got {}",
        inv_denom
    );
}
